const app=document.querySelector('#app'), side=document.querySelector('#nav');
let token=localStorage.adminToken||'', admin=!!token, practice={}, routeHistory=[{key:'home',render:()=>home()}];
const menu=[['🏠 Home','home'],['📚 E-Library','library'],['🎓 Results','results'],['💼 Placements & Internships','placements'],['🛠️ Technical Skills & Resources','technical'],['🎯 Aptitude','aptitude'],['🗣️ Communication & English','communication'],['🎤 Interview Preparation','interview'],['🗺️ Job Preparation Roadmap','roadmap'],['📜 Free Courses & Certifications','courses'],['📝 Resume Builder','resume'],['🚀 Project Ideas','projects'],['📅 Daily Practice','daily'],['📢 Announcements','announcements'],['📅 Academic Calendar','calendar'],['🔗 Useful Links','links']];
const skills=['C/C++','Java','Python','JavaScript','HTML/CSS','SQL','DSA','DBMS','OS','CN','OOP','Web Development','AI/ML','Cloud','Cybersecurity','Embedded/VLSI'];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function api(u,o={}){o.headers={...(o.headers||{})};if(token)o.headers.Authorization='Bearer '+token;const r=await fetch(u,o),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Request failed');return d}
function drawNav(){side.innerHTML='<h3>📚 Explore Portal</h3>'+menu.map(x=>`<button onclick="navigate('${x[1]}')">${x[0]}</button>`).join('')+(admin?`<button onclick="navigate('admin')">⚙️ Admin Dashboard</button>`:'');document.getElementById('ab')?.classList.toggle('hide',admin);document.getElementById('lo')?.classList.toggle('hide',!admin)}
function nav(){side.classList.toggle('open')}
function logout(){localStorage.removeItem('adminToken');token='';admin=false;routeHistory=[{key:'home',render:()=>home()}];drawNav();navigate('home',{reset:true})}

function navigate(p,{reset=false,replace=false}={}){side.classList.remove('open');const entry={key:p,render:()=>render(p)};if(reset)routeHistory=[entry];else if(replace)routeHistory[routeHistory.length-1]=entry;else if(routeHistory[routeHistory.length-1]?.key!==p)routeHistory.push(entry);entry.render()}
function openView(key,fn){side.classList.remove('open');routeHistory.push({key,render:fn});fn()}
function replaceView(key,fn){side.classList.remove('open');routeHistory[routeHistory.length-1]={key,render:fn};fn()}
function goBack(){if(routeHistory.length>1){routeHistory.pop();routeHistory[routeHistory.length-1].render()}else routeHistory[0].render()}
function homeButton(){return `<button class="secondary" onclick="navigate('home',{reset:true})">🏠 Dashboard</button>`}
function backButton(){return `<div class="back-row"><button class="ghost" onclick="goBack()">← Back</button>${routeHistory.length>1?homeButton():''}</div>`}
function page(p){navigate(p)}
function render(p){const f={home,library,results,placements,companyList,questionCompanies,jobAlerts,technical,aptitude,communication,interview,roadmap,courses,resume,projects,daily,announcements,calendar,links,login,admin:adminPage};Promise.resolve((f[p]||home)()).catch(e=>app.innerHTML=`<div class="card error"><h2>Something went wrong</h2><p>${esc(e.message)}</p>${backButton()}</div>`)}
function statCard(icon,value,label,cls=''){return `<div class="stat-card ${cls}"><span class="stat-icon">${icon}</span><strong>${value}</strong><small>${label}</small></div>`}
function sectionHeader(icon,title,subtitle=''){return `<div class="section-head"><div><span class="eyebrow">${icon} STUDENT HUB</span><h1>${title}</h1><p>${subtitle}</p></div>${backButton()}</div>`}
function cardGrid(arr,opts={}){if(!arr.length)return `<div class="empty card"><div>📭</div><h3>No content published yet</h3><p>Admin can add content from the Admin Dashboard.</p></div>`;return `<div class="grid">${arr.map(x=>resourceCard(x,opts)).join('')}</div>`}
function resourceCard(x){return `<article class="card resource-card"><div class="card-top"><span class="icon-bubble">${x.icon||'📘'}</span>${x.category||x.type?`<span class="badge">${esc(x.category||x.type)}</span>`:''}</div><h3>${esc(x.title||x.name||x.company||'Resource')}</h3><p>${esc(x.description||x.overview||'Useful learning material for engineering students.')}</p>${x.url?`<a class="btn" target="_blank" rel="noopener" href="${esc(x.url)}">🔗 Open Resource</a>`:''}</article>`}
function topicCard(icon,title,desc,route,cls=''){return `<article class="feature-card ${cls}"><div class="feature-icon">${icon}</div><div><h3>${title}</h3><p>${desc}</p><button onclick="navigate('${route}')">Explore →</button></div></article>`}
async function home(){let stats={companies:'—',questions:'—',projects:'—',practice:'—'};try{const [c,q,p,d]=await Promise.all([api('/api/companies'),api('/api/placement_questions'),api('/api/projects'),api('/api/daily_practice')]);stats={companies:c.length,questions:q.length.toLocaleString(),projects:p.length,practice:d.length}}catch{}app.innerHTML=`<div class="home-hero"><div class="hero-copy"><span class="eyebrow">🎓 ALL-IN-ONE ENGINEERING STUDENT PLATFORM</span><h1>Learn. Practice. Build. <span>Prepare.</span></h1><p>Your complete space for academics, technical skills, placements, interviews, projects, courses and daily practice.</p><div class="hero-actions"><button onclick="navigate('placements')">🚀 Explore Placements</button><button class="light-btn" onclick="navigate('roadmap')">🗺️ Start a Roadmap</button></div><div class="creator">Created by <b>Adarsh Anand Patil</b></div></div><div class="hero-visual"><div class="orb orb1"></div><div class="orb orb2"></div><div class="floating-card fc1">💻<b>Skills</b><small>Learn & practice</small></div><div class="floating-card fc2">🎯<b>Placements</b><small>Prepare smarter</small></div><div class="floating-card fc3">🚀<b>Projects</b><small>Build your portfolio</small></div><div class="hero-rocket">🎓</div></div></div><div class="stats-row">${statCard('🏢',stats.companies,'Companies', 's-purple')}${statCard('📝',stats.questions,'Placement Questions','s-orange')}${statCard('🚀',stats.projects,'Project Ideas','s-green')}${statCard('🎯',stats.practice,'Daily Practice','s-pink')}</div><div class="section-title"><div><span class="eyebrow">EXPLORE</span><h2>Everything students need in one portal</h2></div><p>Open any section to begin.</p></div><div class="feature-grid">${topicCard('📚','E-Library','Notes, PDFs, labs, assignments, examples and videos.','library','purple')}${topicCard('🎓','Results','SGPA, CGPA, percentage and official VTU results.','results','gold')}${topicCard('💼','Placements & Internships','Company directory, placement questions and job alerts.','placements','orange')}${topicCard('🛠️','Technical Skills','Skill resources, practice, projects and interview preparation.','technical','teal')}${topicCard('🎤','Interview Preparation','HR, technical, project, coding and AI mock interview practice.','interview','pink')}${topicCard('🗺️','Job Preparation Roadmap','Choose a career path and follow a complete preparation plan.','roadmap','violet')}${topicCard('📜','Free Courses & Certifications','Courses from the seven selected learning platforms.','courses','green')}${topicCard('📝','Resume Builder','Create and print a placement-ready resume.','resume','rose')}${topicCard('🚀','Project Ideas','Real-world ideas with tutorials, datasets and deployment references.','projects','amber')}${topicCard('📅','Daily Practice','15–25 question practice sessions with answers and explanations.','daily','cyan')}${topicCard('📢','Announcements','Important student updates and notices.','announcements','red')}${topicCard('📅','Academic Calendar','Academic events and important dates.','calendar','indigo')}${topicCard('🔗','Useful Links','Quick access to important student websites.','links','lime')}</div><div class="home-strip"><div><b>💡 Build your career step by step</b><span>Study → Practice → Build → Interview → Apply</span></div><button onclick="navigate('daily')">Start Daily Practice →</button></div>`}
async function library(){const d=await api('/api/resources');const apna=[['C/C++','https://www.youtube.com/@ApnaCollegeOfficial/search?query=C%2B%2B'],['Java','https://www.youtube.com/@ApnaCollegeOfficial/search?query=Java'],['Python','https://www.youtube.com/@ApnaCollegeOfficial/search?query=Python'],['JavaScript','https://www.youtube.com/@ApnaCollegeOfficial/search?query=JavaScript'],['DSA','https://www.youtube.com/@ApnaCollegeOfficial/search?query=DSA'],['Web Development','https://www.youtube.com/@ApnaCollegeOfficial/search?query=Web%20Development'],['SQL/DBMS','https://www.youtube.com/@ApnaCollegeOfficial/search?query=SQL%20DBMS']];app.innerHTML=`${sectionHeader('📚','E-Library','A colorful learning shelf for notes, labs, assignments, examples, videos and websites.')}<div class="mini-stats">${statCard('📖',d.length,'Published Resources')}${statCard('🎥',apna.length,'Apna College Subjects')}</div>${cardGrid(d)}<div class="panel colorful-panel"><div class="panel-title"><span>🎥</span><div><h2>Apna College Video Lectures</h2><p>Course-wise links to the official Apna College YouTube channel.</p></div></div><div class="chip-grid">${apna.map(a=>`<a class="resource-chip" target="_blank" rel="noopener" href="${a[1]}">▶ ${esc(a[0])}</a>`).join('')}</div></div>`}
async function results(){
 const d=await api('/api/results');
 const sem=[1,2,3,4,5,6,7,8];
 const records=sem.map(n=>d.find(x=>String(x.semester)===String(n)&&x.type==='semester')||d.find(x=>String(x.semester)===String(n)));
 const entered=records.filter(Boolean).filter(x=>Number.isFinite(Number(x.sgpa)));
 const weightedCredits=entered.reduce((a,x)=>a+(Number(x.credits)||0),0);
 const cgpa=entered.length?(weightedCredits>0?entered.reduce((a,x)=>a+(Number(x.sgpa)||0)*(Number(x.credits)||0),0)/weightedCredits:entered.reduce((a,x)=>a+(Number(x.sgpa)||0),0)/entered.length):null;
 const pct=cgpa==null?null:Math.max(0,Math.min(100,(cgpa-0.75)*10));
 const fmt=v=>v==null?'—':Number(v).toFixed(2);
 app.innerHTML=`${sectionHeader('🎓','Results','Enter semester SGPA through Admin and the portal automatically calculates CGPA and VTU-style percentage.')}
 <div class="result-hero result-hero-v2"><div><span class="eyebrow">ACADEMIC PERFORMANCE</span><h2>Semester Result Dashboard</h2><p>Use the official VTU result page to check your result. This portal does not ask for your VTU username, password or login details.</p><div class="result-actions"><a class="btn" target="_blank" rel="noopener" href="https://totalresults.vtu.ac.in/">🌐 Open Official VTU Results</a><span class="result-note">🔒 No VTU login details are collected here.</span></div></div><div class="result-orb">🎓<small>${entered.length}/8 Semesters</small></div></div>
 <div class="result-summary-grid">
  <article class="result-stat rs-purple"><span>📈</span><small>Overall CGPA</small><strong>${fmt(cgpa)}</strong><p>${entered.length?'Calculated automatically':'Enter SGPA through Admin'}</p></article>
  <article class="result-stat rs-orange"><span>📊</span><small>Percentage</small><strong>${pct==null?'—':fmt(pct)+'%'}</strong><p>${pct==null?'Enter SGPA through Admin':'Calculated from CGPA'}</p></article>
  <article class="result-stat rs-teal"><span>🎓</span><small>Semesters Recorded</small><strong>${entered.length}</strong><p>Out of 8 semesters</p></article>
 </div>
 <div class="result-formula"><b>🧮 Automatic calculation</b><span>CGPA uses entered SGPA values. If semester credits are entered in Admin, the calculation is credit-weighted; otherwise the entered SGPAs are averaged.</span><span>VTU B.E./B.Tech. 2021-22 regulations specify the final percentage conversion as <b>(CGPA − 0.75) × 10</b> after completion of the programme.</span></div>
 <h2 class="subsection-title">Semester Performance</h2>
 <div class="semester-grid semester-grid-v2">${sem.map(n=>{const r=records[n-1];return `<article class="semester-card sem-${(n-1)%6}"><div class="sem-icon">📘</div><div><small>Semester ${n}</small><strong>${r?.sgpa!=null?fmt(r.sgpa):'—'}</strong><span>${r?.sgpa!=null?'SGPA':'Not entered'}</span>${r?.credits?`<em>${esc(r.credits)} credits</em>`:''}</div></article>`}).join('')}</div>
 <div class="subject-note">📌 Subject-wise records can include <b>subject name, credits, grade, grade point and result status</b> when published by Admin.</div>`
}
async function placements(){const [cs,jobs,ps,qs]=await Promise.all([api('/api/companies'),api('/api/jobs'),api('/api/job_platforms'),api('/api/placement_questions')]);app.innerHTML=`${sectionHeader('💼','Placements & Internships','Your central career hub: companies, question banks, job alerts and internships.')}<div class="placement-banner"><div><span class="eyebrow">CAREER HUB</span><h2>Prepare from fundamentals to application</h2><p>Research companies, practice company-style questions, then find jobs and internships through trusted platforms.</p></div><div class="banner-badge">${cs.length}<small>Companies</small></div></div><div class="grid two-wide">${topicCard('🏢','Placement Hub',`${cs.length} companies with roles, study areas, preparation guidance and official links.`,'companyList','orange')}${topicCard('📝','Previous Placement Questions',`${qs.length.toLocaleString()} company question-bank entries organized by company and category.`,'questionCompanies','purple')}${topicCard('🔔','Job Alerts',`${jobs.length} job/internship records. Internships are included here, not as a separate section.`,'jobAlerts','green')}</div><div class="panel"><div class="panel-title"><span>🌐</span><div><h2>Job & Internship Platforms</h2><p>Open the official platform websites to search current opportunities.</p></div></div><div class="chip-grid">${ps.map(x=>`<a class="resource-chip" target="_blank" rel="noopener" href="${esc(x.url)}">${esc(x.name)}</a>`).join('')}</div></div>`}
async function companyList(){const d=await api('/api/companies');app.innerHTML=`${sectionHeader('🏢','Placement Hub','Explore companies by role, study areas, preparation guidance and official careers links.')}<div class="toolbar"><input id="cq" placeholder="🔎 Search company..." oninput="filterCompanies()"><select id="ct" onchange="filterCompanies()"><option value="">All tiers</option><option>Tier 1</option><option>Tier 2</option><option>Tier 3</option></select></div><div id="companyGrid" class="company-grid">${d.map(companyCard).join('')}</div>`;window.companyData=d}
function companyCard(c){return `<article class="company-card"><div class="company-logo">${esc((c.name||'C').split(' ').map(x=>x[0]).join('').slice(0,3))}</div><div class="company-info"><div class="company-line"><span class="badge">${esc(c.tier||'Company')}</span><span class="small">${(c.roles||[]).length} common roles</span></div><h2>${esc(c.name)}</h2><p>${esc(c.officialInfo?.overview||'Research current roles, skills and hiring requirements on official sources.')}</p><div class="tag-cloud">${(c.study||[]).slice(0,5).map(x=>`<span>${esc(x)}</span>`).join('')}</div><button onclick="openView('company:'+${c.id},()=>companyInfo(${c.id}))">Open Company →</button></div></article>`}
function filterCompanies(){const q=(document.getElementById('cq')?.value||'').toLowerCase(),t=document.getElementById('ct')?.value||'';document.getElementById('companyGrid').innerHTML=window.companyData.filter(c=>(!q||c.name.toLowerCase().includes(q))&&(!t||c.tier===t)).map(companyCard).join('')||`<div class="empty card">No company matches your search.</div>`}
async function companyInfo(id){const c=(await api('/api/companies')).find(x=>String(x.id)===String(id));const qs=(await api('/api/placement_questions')).filter(x=>x.company===c.name);app.innerHTML=`${sectionHeader('🏢',c.name,'Company profile, preparation guide, question bank and official links.')}<div class="profile-hero"><div class="company-logo big">${esc(c.name.split(' ').map(x=>x[0]).join('').slice(0,3))}</div><div><span class="badge">${esc(c.tier||'Company')}</span><h2>Research • Prepare • Practice • Apply</h2><p>${esc(c.officialInfo?.overview||'Use the official company sources for current hiring information.')}</p></div></div><div class="grid"><div class="card"><h3>💼 Common Roles</h3><div class="tag-cloud">${(c.roles||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="card"><h3>📚 What to Study</h3><div class="tag-cloud">${(c.study||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></div><div class="card"><h2>🎯 Preparation Guide</h2><ol class="step-list">${(c.prepare||[]).map((x,i)=>`<li><b>${i+1}</b><span>${esc(x)}</span></li>`).join('')}</ol></div><div class="link-list"><a class="btn" target="_blank" rel="noopener" href="${esc(c.official)}">🌐 Official Website</a><a class="btn secondary" target="_blank" rel="noopener" href="${esc(c.careers||c.official)}">💼 Official Careers</a><button onclick="openView('companyQuestions:'+${c.id},()=>companyQuestions(${c.id}))">📝 Question Bank (${qs.length})</button></div><div class="card"><h3>📝 Question Bank Preview</h3><p class="small">These are company-focused practice entries unless a source is explicitly identified. Verify current hiring patterns on official company sources.</p>${qs.slice(0,6).map(questionCard).join('')}</div>`}
async function questionCompanies(){const cs=await api('/api/companies'),qs=await api('/api/placement_questions');app.innerHTML=`${sectionHeader('📝','Previous Placement Questions','Select a company, then practice Aptitude, Coding, Technical, SQL, HR and Interview categories.')}<div class="question-hero"><span>🧠</span><div><h2>Company-wise practice</h2><p>Question banks are organized by company and category. Entries marked as practice are not claimed as verified historical interview questions.</p></div></div><div class="toolbar"><input id="qq" placeholder="🔎 Search company..." oninput="filterQuestionCompanies()"></div><div id="qcompanyGrid" class="company-grid">${cs.map(c=>questionCompanyCard(c,qs)).join('')}</div>`;window.qCompanyData={cs,qs}}
function questionCompanyCard(c,qs){const q=qs.filter(x=>x.company===c.name),cats=['Aptitude','Coding','Technical','SQL','HR','Interview'];return `<article class="company-card question-company"><div class="company-logo">${esc(c.name.split(' ').map(x=>x[0]).join('').slice(0,3))}</div><div class="company-info"><span class="badge">${q.length} entries</span><h2>${esc(c.name)}</h2><div class="cat-counts">${cats.map(cat=>`<span>${cat} <b>${q.filter(x=>x.category===cat).length}</b></span>`).join('')}</div><button onclick="openView('companyQuestions:'+${c.id},()=>companyQuestions(${c.id}))">Open Question Bank →</button></div></article>`}
function filterQuestionCompanies(){const q=(document.getElementById('qq')?.value||'').toLowerCase();document.getElementById('qcompanyGrid').innerHTML=window.qCompanyData.cs.filter(c=>c.name.toLowerCase().includes(q)).map(c=>questionCompanyCard(c,window.qCompanyData.qs)).join('')}
async function companyQuestions(id){const c=(await api('/api/companies')).find(x=>String(x.id)===String(id)),qs=(await api('/api/placement_questions')).filter(x=>x.company===c.name),cats=['Aptitude','Coding','Technical','SQL','HR','Interview'];app.innerHTML=`${sectionHeader('📝',`${esc(c.name)} Question Bank`,'Choose a category to practice company-focused questions.')}<div class="category-grid">${cats.map((cat,i)=>`<article class="category-card c${i}"><div>${['🎯','💻','🧠','🗄️','🗣️','🎤'][i]}</div><h3>${cat}</h3><strong>${qs.filter(q=>q.category===cat).length}</strong><p>questions</p><button onclick="openView('companyQs:${encodeURIComponent(c.name)}:${cat}',()=>showCompanyQs('${encodeURIComponent(c.name)}','${cat}'))">Practice →</button></article>`).join('')}</div><div class="notice">📌 Question-bank entries are company-focused practice unless a source is explicitly identified. Current recruitment patterns can change, so check the company's official careers page.</div>`}
function questionCard(q){return `<div class="qcard"><span class="badge">${esc(q.category||q.round||'Practice')}</span><h3>${esc(q.question)}</h3><p><b>Answer:</b> ${esc(q.answer)}</p><details><summary>View explanation</summary><p>${esc(q.explanation||'Review the underlying concept and explain your reasoning clearly.')}</p></details></div>`}
async function showCompanyQs(enc,cat){const name=decodeURIComponent(enc),qs=(await api('/api/placement_questions')).filter(x=>x.company===name&&x.category===cat);app.innerHTML=`${sectionHeader('📝',`${esc(name)} • ${esc(cat)}`,'Practice questions with answers and explanations.')}<div class="question-toolbar"><span class="badge">${qs.length} questions</span><span class="small">Company-focused practice</span></div>${qs.map(questionCard).join('')}`}
async function jobAlerts(){const [jobs,platforms]=await Promise.all([api('/api/jobs'),api('/api/job_platforms')]);app.innerHTML=`${sectionHeader('🔔','Job Alerts','Full-time jobs and internships are included together in this section.')}<div class="notice">⚠️ Job listings change frequently. Verify eligibility, deadline and employer details on the official listing before applying.</div><div class="toolbar"><input id="jq" placeholder="🔎 Search role/company..." oninput="filterJobs()"><select id="jt" onchange="filterJobs()"><option value="">All opportunities</option><option value="Internship">Internships</option><option value="Job">Jobs</option></select></div><div id="jobGrid" class="grid">${jobs.map(jobCard).join('')}</div><div class="panel"><h2>🌐 Search more jobs & internships</h2><div class="chip-grid">${platforms.map(x=>`<a class="resource-chip" target="_blank" rel="noopener" href="${esc(x.url)}">${esc(x.name)}</a>`).join('')}</div></div>`;window.jobsData=jobs}
function jobCard(x){const kind=(x.type||x.kind||'Job');return `<article class="card job-card"><div class="card-top"><span class="icon-bubble">${/intern/i.test(kind)?'🎓':'💼'}</span><span class="badge">${esc(kind)}</span></div><h3>${esc(x.title||x.role||'Opportunity')}</h3><p><b>${esc(x.company||'Company')}</b>${x.location?' • '+esc(x.location):''}</p><p>${esc(x.description||'Check the official listing for current requirements and deadlines.')}</p>${x.url?`<a class="btn" target="_blank" rel="noopener" href="${esc(x.url)}">Apply / View →</a>`:''}</article>`}
function filterJobs(){const q=(document.getElementById('jq')?.value||'').toLowerCase(),t=document.getElementById('jt')?.value||'';document.getElementById('jobGrid').innerHTML=window.jobsData.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!t||(x.type||x.kind||'Job')===t)).map(jobCard).join('')}
async function technical(){const d=await api('/api/technical_resources'),published=d.filter(x=>x.published!==false),skillList=[...new Set(published.map(x=>x.skill))];app.innerHTML=`${sectionHeader('🛠️','Technical Skills & Resources','Skill-specific notes, PDFs, videos, useful links, practice, projects and interview preparation.')}<div class="skill-intro"><span>⚡</span><div><h2>Build job-ready technical skills</h2><p>Select a skill to see focused resources and practice routes.</p></div></div><div class="skill-grid">${skillList.map((s,i)=>`<article class="skill-card sc${i%8}"><div class="skill-icon">${['💻','☕','🐍','🟨','🌐','🗄️','🧩','🧠'][i%8]}</div><h3>${esc(s)}</h3><p>${published.filter(x=>x.skill===s).length} resources</p><div><span>📚 Notes</span><span>🎥 Videos</span><span>💻 Practice</span></div><button onclick="openView('skill:${encodeURIComponent(s)}',()=>skill('${encodeURIComponent(s)}'))">Open Skill →</button></article>`).join('')}</div>`}
async function skill(enc){const s=decodeURIComponent(enc),d=(await api('/api/technical_resources')).filter(x=>x.skill===s&&x.published!==false);const notes=d.filter(x=>/pdf|notes/i.test(x.type)||/notes|fundamentals/i.test(x.title)),videos=d.filter(x=>/video|apna/i.test(x.type)),other=d.filter(x=>!notes.includes(x)&&!videos.includes(x));app.innerHTML=`${sectionHeader('🛠️',`${esc(s)} Skill Hub`,'Study → Practice → Build → Interview.')}<div class="skill-banner"><div class="skill-icon big">💡</div><div><h2>${esc(s)}</h2><p>Use these resources to build fundamentals and prepare for technical rounds.</p></div></div><div class="resource-tabs"><div class="panel"><h2>📚 Notes & PDFs</h2>${cardGrid(notes)}</div><div class="panel"><h2>🎥 Video Resources</h2>${cardGrid(videos)}</div><div class="panel"><h2>🔗 Other Useful Resources</h2>${cardGrid(other)}</div></div><div class="action-panel"><button onclick="startPractice('Technical')">💻 Technical Daily Practice</button><button class="secondary" onclick="openView('interview:${encodeURIComponent(s)}',()=>interviewBy('${encodeURIComponent(s)}'))">🎤 Interview Questions</button><button class="secondary" onclick="navigate('projects')">🚀 Related Projects</button></div>`}
async function aptitude(){await practiceCategory('Aptitude','🎯','Aptitude Practice','Quantitative aptitude, reasoning, verbal ability and placement-style problem solving.')}
async function communication(){await practiceCategory('Communication & English','🗣️','Communication & English','Grammar, vocabulary, comprehension and workplace communication practice.')}
async function practiceCategory(cat,icon,title,desc){const d=await api('/api/daily_practice'),qs=d.filter(x=>x.category===cat);app.innerHTML=`${sectionHeader(icon,title,desc)}<div class="practice-launch"><div><h2>Ready for a timed practice session?</h2><p>Get 15–25 MCQs with immediate answer and explanation after each response.</p></div><div class="launch-number">${qs.length}<small>bank questions</small></div></div><button onclick="startPractice('${encodeURIComponent(cat)}')">🚀 Start Practice Test</button>`}
async function interview(){const d=await api('/api/interview_questions'),cats=[...new Set(d.map(x=>x.category))];app.innerHTML=`${sectionHeader('🎤','Interview Preparation','Prepare for HR, technical, project, coding and domain interviews. AI Mock Interview is included here.')}<div class="interview-hero"><div class="ai-avatar">🤖</div><div><span class="eyebrow">INTERACTIVE PRACTICE</span><h2>Practice questions and speak your answer</h2><p>Use text or voice input. If you do not know an answer, reveal a sample answer and explanation.</p><button onclick="openView('mockInterview',()=>startMockInterview())">🤖 Start AI Mock Interview</button></div></div><div class="category-grid">${cats.map((c,i)=>`<article class="category-card c${i%6}"><div>🎤</div><h3>${esc(c)}</h3><strong>${d.filter(x=>x.category===c).length}</strong><p>questions</p><button onclick="openView('interview:${encodeURIComponent(c)}',()=>interviewBy('${encodeURIComponent(c)}'))">Practice →</button></article>`).join('')}</div>`}
async function interviewBy(enc){const cat=decodeURIComponent(enc),d=await api('/api/interview_questions');let qs=d.filter(x=>x.category===cat||JSON.stringify(x).toLowerCase().includes(cat.toLowerCase()));if(!qs.length)qs=d.slice(0,10);app.innerHTML=`${sectionHeader('🎤',`${esc(cat)} Interview Questions`,'Actual interview-style questions with sample answers and explanations.')}<div class="question-list">${qs.map((q,i)=>`<article class="qcard interview-q"><div class="qnum">${String(i+1).padStart(2,'0')}</div><div><span class="badge">${esc(q.category)}</span><h3>${esc(q.question)}</h3><details><summary>Show sample answer</summary><div class="sample-answer"><b>Sample Answer</b><p>${esc(q.answer)}</p><b>Why this works</b><p>${esc(q.explanation)}</p></div></details></div></article>`).join('')}</div>`}
async function startMockInterview(){const d=await api('/api/interview_questions');practice={mode:'mock',qs:d.sort(()=>Math.random()-.5).slice(0,10),i:0,score:0,unknown:0,voice:null};showMock()}
function showMock(){const q=practice.qs[practice.i],pct=Math.round(practice.i/practice.qs.length*100);app.innerHTML=`<div class="mock-shell">${sectionHeader('🤖','AI Mock Interview','Practice one question at a time and reveal a sample answer when needed.')}<div class="mock-card"><div class="progress"><div style="width:${pct}%"></div></div><div class="mock-meta"><span>${practice.i+1} / ${practice.qs.length}</span><span class="badge">${esc(q.category)}</span></div><h2>${esc(q.question)}</h2><textarea id="mockAnswer" placeholder="Type your answer here..."></textarea><div class="mock-actions"><button onclick="startVoice('mockAnswer')">🎙️ Voice Input</button><button class="secondary" onclick="dontKnowMock()">🤷 I Don't Know</button><button onclick="submitMock()">Submit Answer →</button></div><div id="mockFeedback"></div></div></div>`}
function startVoice(target){if(!('webkitSpeechRecognition' in window||'SpeechRecognition' in window)){alert('Voice input is not supported by this browser. You can type your answer.');return}const R=window.SpeechRecognition||window.webkitSpeechRecognition,r=new R();r.lang='en-IN';r.interimResults=false;r.onresult=e=>document.getElementById(target).value=e.results[0][0].transcript;r.start()}
function submitMock(){const q=practice.qs[practice.i],a=(document.getElementById('mockAnswer').value||'').trim();if(!a){alert('Type or speak an answer first, or choose I Don’t Know.');return}document.getElementById('mockFeedback').innerHTML=`<div class="notice"><b>Sample Answer</b><p>${esc(q.answer)}</p><b>How to improve your response</b><p>${esc(q.explanation)}</p></div><button onclick="nextMock()">Next Question →</button>`}
function dontKnowMock(){practice.unknown++;const q=practice.qs[practice.i];document.getElementById('mockFeedback').innerHTML=`<div class="notice"><b>Here is a sample answer</b><p>${esc(q.answer)}</p><b>Explanation</b><p>${esc(q.explanation)}</p></div><button onclick="nextMock()">Next Question →</button>`}
function nextMock(){practice.i++;if(practice.i>=practice.qs.length){app.innerHTML=`<div class="completion"><div>🎉</div><h1>Mock Interview Complete</h1><p>You completed ${practice.qs.length} questions.</p><p>I Don't Know used: ${practice.unknown}</p><button onclick="interview()">Practice Again</button></div>`}else showMock()}
async function roadmap(){const paths=['Python Full Stack','Java Full Stack','Java Developer','Python Developer','Frontend Developer','Data Analyst','AI / ML Engineer','Cloud Engineer','Cybersecurity Engineer','Embedded Engineer','VLSI Engineer'];app.innerHTML=`${sectionHeader('🗺️','Job Preparation Roadmap','Select the career path you want to prepare for. The roadmap changes according to your selection.')}<div class="roadmap-select">${paths.map((p,i)=>`<button class="path-card pc${i%8}" onclick="openView('roadmap:${encodeURIComponent(p)}',()=>openRoadmap('${encodeURIComponent(p)}'))"><span>${['🐍','☕','💻','🐍','🎨','📊','🤖','☁️','🔐','🔌','⚙️'][i]}</span><b>${p}</b><small>Open complete roadmap →</small></button>`).join('')}</div>`}
