function openRoadmap(enc){const p=decodeURIComponent(enc),stages=roadmapData[p]||roadmapData['Python Full Stack'];app.innerHTML=`${sectionHeader('🗺️',`${esc(p)} — Preparation Roadmap`,'Follow this role-specific path from fundamentals to projects, interviews and applications.')}<div class="roadmap-timeline">${stages.map((s,i)=>`<article class="road-stage"><div class="road-num">${i+1}</div><div class="road-content"><div class="road-head"><span class="badge">STAGE ${i+1}</span><h2>${esc(s[0])}</h2></div><p>${esc(s[1])}</p><div class="road-columns"><div><b>🧪 What to practice / build</b><p>${esc(s[2])}</p></div><a class="resource-chip" target="_blank" rel="noopener" href="${esc(s[3])}">📚 Study Resource →</a></div></div></article>`).join('')}</div><div class="home-strip"><div><b>🏁 End-to-end checklist</b><span>Study → Practice → Build → Test → Deploy → Interview → Resume → Apply</span></div><button onclick="navigate('resume')">Build Resume →</button></div>`}
async function courses(){const d=await api('/api/courses'),providers=[...new Set(d.map(x=>x.provider))];app.innerHTML=`${sectionHeader('📜','Free Courses & Certifications','Selected learning platforms only. Course access, certificates and paid features can vary by individual course.')}<div class="platform-strip">${providers.map(p=>`<span>${esc(p)}</span>`).join('')}</div><div class="course-grid">${d.map(courseCard).join('')}</div>`}
function courseCard(x){return `<article class="course-card"><div class="course-top"><span class="provider-logo">${esc((x.provider||'L').slice(0,2).toUpperCase())}</span><span class="badge">${x.free?'Free learning':'Free / Paid varies'}</span></div><h2>${esc(x.title)}</h2><p><b>Platform:</b> ${esc(x.provider)}</p><div class="course-meta"><span>🎓 Certificate: ${esc(x.certificate||'Course dependent')}</span><span>📌 ${esc(x.area||'Skills & career preparation')}</span></div><p>${esc(x.description||'Build practical skills through structured learning.')}</p><a class="btn" target="_blank" rel="noopener" href="${esc(x.url)}">Open Official Course →</a></article>`}
async function resume(){app.innerHTML=`${sectionHeader('📝','Resume Builder','Create a complete ATS-friendly placement resume, preview it professionally, and print/save it as PDF.')}<div class="resume-layout"><div class="card form-card"><h2>📋 Resume Details</h2><p class="small">Fill the sections that apply to you. Keep the final resume concise and role-focused.</p><label>Full Name<input id="rn" placeholder="Your full name"></label><label>Email<input id="re" placeholder="you@example.com"></label><label>Phone<input id="rpone" placeholder="+91 ..."></label><label>LinkedIn<input id="rlin" placeholder="https://linkedin.com/in/..." ></label><label>GitHub<input id="rgh" placeholder="https://github.com/..." ></label><label>Portfolio<input id="rport" placeholder="https://..." ></label><label>Career Objective / Professional Summary<textarea id="rsummary" placeholder="2–4 lines focused on the role you want."></textarea></label><label>Education<textarea id="redu" placeholder="Degree | College | University | Year | CGPA/Percentage"></textarea></label><label>Technical Skills<textarea id="rs" placeholder="Languages, frameworks, databases, tools..."></textarea></label><label>Projects<textarea id="rproj" placeholder="Project name — technologies — what you built, your role and outcome."></textarea></label><label>Internship / Experience<textarea id="rexp" placeholder="Company | Role | Duration | responsibilities and achievements"></textarea></label><label>Achievements<textarea id="rach" placeholder="Hackathons, awards, coding achievements, academic achievements..."></textarea></label><label>Certifications<textarea id="rcert" placeholder="Certification | Provider | Year"></textarea></label><label>Relevant Coursework<textarea id="rcourse" placeholder="DSA, DBMS, OS, CN, OOP, Web Development..."></textarea></label><label>Soft Skills<textarea id="rsoft" placeholder="Communication, teamwork, leadership, problem solving..."></textarea></label><label>Positions of Responsibility<textarea id="rpor" placeholder="Club, event, coordinator role..."></textarea></label><button onclick="makeResume()">✨ Generate Resume Preview</button></div><div id="rv" class="resume-preview"><div class="empty"><div>📝</div><h3>Your resume preview will appear here</h3><p>Generate it after filling your details.</p></div></div></div><div class="panel colorful-panel resume-resources"><div class="panel-title"><span>📚</span><div><h2>Resume Resources</h2><p>Guides for ATS, projects, LinkedIn, applications and fresher resumes.</p></div></div><div class="resource-grid"><article><b>🎯 ATS Guidance</b><p>Use standard headings, readable formatting, relevant keywords and avoid unnecessary graphics in the final resume.</p><a class="resource-chip" target="_blank" href="https://www.linkedin.com/pulse/topics/resume-writing-s50171/">Open Guide →</a></article><article><b>🧩 Project Descriptions</b><p>Write project bullets around the problem, technology, your contribution and measurable result.</p><a class="resource-chip" target="_blank" href="https://developer.mozilla.org/en-US/docs/Learn">Project Learning Reference →</a></article><article><b>💼 Fresher Tips</b><p>Keep the resume focused on skills, strong academic projects, internships, certifications and achievements.</p><a class="resource-chip" target="_blank" href="https://www.linkedin.com/jobs/">Explore Roles →</a></article><article><b>🔗 LinkedIn Profile</b><p>Align your headline, About section, skills and projects with the roles you are applying for.</p><a class="resource-chip" target="_blank" href="https://www.linkedin.com/">Open LinkedIn →</a></article><article><b>📝 Resume Examples</b><p>Compare role-specific resume structures before finalizing your own one-page version.</p><a class="resource-chip" target="_blank" href="https://www.overleaf.com/latex/templates/tagged/cv">View Templates →</a></article><article><b>🎤 Interview + Applications</b><p>Prepare your project explanation and keep an application tracker for every company and role.</p><a class="resource-chip" target="_blank" href="https://www.interviewbit.com/">Interview Practice →</a></article></div></div>`}
function makeResume(){const g=id=>esc(document.getElementById(id)?.value||'');const section=(title,id)=>{const v=g(id);return v?`<section><h3>${title}</h3><p>${v.split('\n').join('<br>')}</p></section>`:''};document.getElementById('rv').innerHTML=`<div class="resume-paper"><header><h1>${g('rn')||'Your Name'}</h1><p>${[g('re'),g('rpone'),g('rlin'),g('rgh'),g('rport')].filter(Boolean).join(' • ')}</p></header>${section('Professional Summary','rsummary')}${section('Education','redu')}${section('Technical Skills','rs')}${section('Projects','rproj')}${section('Internship / Experience','rexp')}${section('Achievements','rach')}${section('Certifications','rcert')}${section('Relevant Coursework','rcourse')}${section('Soft Skills','rsoft')}${section('Positions of Responsibility','rpor')}<div class="resume-actions"><button onclick="window.print()">📥 Print / Save as PDF</button></div></div>`}
async function projects(){const d=await api('/api/projects');app.innerHTML=`${sectionHeader('🚀','Project Ideas','Real-world project ideas with project-specific tutorials, references, datasets and deployment resources.')}<div class="toolbar"><input id="pq" placeholder="🔎 Search projects..." oninput="filterProjects()"></div><div id="projectGrid" class="project-grid">${d.map(projectCard).join('')}</div>`;window.projectData=d}
function projectCard(x){const refs=x.references||[];return `<article class="project-card"><div class="project-cover">🚀<span>${esc(x.difficulty||'Project')}</span></div><div class="project-body"><h2>${esc(x.title)}</h2><div class="tag-cloud"><span>${esc(x.category||'General')}</span><span>${esc(x.difficulty||'')}</span><span>${esc(x.technologies||'')}</span></div><h4>❓ Problem</h4><p>${esc(x.problem||'')}</p><h4>💡 Solution idea</h4><p>${esc(x.description||'')}</p><div class="link-list">${x.tutorial?resourceButtons(x.tutorial,'📺 Tutorial'):''}${refs.map(u=>resourceButtons(u,'💻 Reference')).join('')}${x.datasets?resourceButtons(x.datasets,'📊 Dataset'):''}${x.deployment?resourceButtons(x.deployment,'☁️ Deployment'):''}<a class="btn secondary" target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent((x.title||'project')+' project tutorial')}">▶ More Videos</a><a class="btn secondary" target="_blank" rel="noopener" href="https://github.com/search?q=${encodeURIComponent(x.title||'project')}&type=repositories">GitHub References</a></div></div></article>`}
function resourceButtons(url,title){return url?`<a class="btn" target="_blank" rel="noopener" href="${esc(url)}">${esc(title)}</a>`:''}
function filterProjects(){const q=(document.getElementById('pq')?.value||'').toLowerCase();document.getElementById('projectGrid').innerHTML=window.projectData.filter(x=>JSON.stringify(x).toLowerCase().includes(q)).map(projectCard).join('')}
async function daily(){const cats=[['Aptitude','🎯','Quantitative aptitude, reasoning and placement problem solving.'],['Technical','🛠️','Programming, OOP, DSA, DBMS, SQL, OS and CN.'],['Communication & English','🗣️','Grammar, vocabulary and workplace communication.'],['Interview','🎤','Actual interview-style HR, technical and project questions.'],];app.innerHTML=`${sectionHeader('📅','Daily Practice','Choose a category, then complete a 15–25 question MCQ session with instant explanations.')}<div class="practice-grid">${cats.map((c,i)=>`<article class="practice-card pc${i}"><div>${c[1]}</div><h2>${c[0]}</h2><p>${c[2]}</p><button onclick="startPractice('${encodeURIComponent(c[0])}')">Start 15–25 Questions →</button></article>`).join('')}</div>`}
async function startPractice(enc){const cat=decodeURIComponent(enc),d=await api('/api/daily_practice');let pool=d.filter(x=>x.category===cat);if(cat==='Interview'&&!pool.length)pool=(await api('/api/interview_questions')).map(x=>({category:'Interview',topic:x.category,question:x.question,options:['A sample response','A definition without context','I would skip the question','None of these'],answer:'A sample response',explanation:x.answer}));pool=pool.sort(()=>Math.random()-.5);if(pool.length<15){alert('This category currently has fewer than 15 questions. Admin can add more questions.');return}practice={cat,qs:pool.slice(0,Math.min(25,pool.length)),i:0,score:0,unknown:0};openView('practice:'+cat,()=>showPractice())}
function showPractice(){const q=practice.qs[practice.i],pct=Math.round(practice.i/practice.qs.length*100);app.innerHTML=`<div class="practice-shell">${sectionHeader('📅',`${esc(practice.cat)} Practice`,'Answer each question, or choose I Don’t Know to reveal the correct answer.')}<div class="practice-card active"><div class="mock-meta"><span>Question ${practice.i+1} / ${practice.qs.length}</span><span class="badge">${esc(q.topic||'Practice')}</span></div><div class="progress"><div style="width:${pct}%"></div></div><h2>${esc(q.question)}</h2><div class="options">${(q.options||[]).map((o,i)=>`<button class="option" onclick="answerPractice(${i})">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="secondary" onclick="dontKnowPractice()">🤷 I Don’t Know</button><div id="pf"></div></div></div>`}
function answerPractice(i){const q=practice.qs[practice.i],choice=q.options[i],ok=choice===q.answer;if(ok)practice.score++;document.querySelectorAll('.option').forEach(b=>b.disabled=true);document.getElementById('pf').innerHTML=`<div class="notice ${ok?'success':'danger'}"><b>${ok?'✅ Correct':'❌ Not quite'}</b><p><b>Correct Answer:</b> ${esc(q.answer)}</p><p><b>Explanation:</b> ${esc(q.explanation||'')}</p></div><button onclick="nextPractice()">Next Question →</button>`}
function dontKnowPractice(){const q=practice.qs[practice.i];practice.unknown++;document.querySelectorAll('.option').forEach(b=>b.disabled=true);document.getElementById('pf').innerHTML=`<div class="notice"><b>💡 Learn this</b><p><b>Correct Answer:</b> ${esc(q.answer)}</p><p><b>Explanation:</b> ${esc(q.explanation||'')}</p></div><button onclick="nextPractice()">Next Question →</button>`}
function nextPractice(){practice.i++;if(practice.i>=practice.qs.length){app.innerHTML=`<div class="completion"><div>🏆</div><h1>Practice Complete!</h1><h2>${practice.score} / ${practice.qs.length}</h2><p>Accuracy: ${Math.round(practice.score/practice.qs.length*100)}% • I Don’t Know: ${practice.unknown}</p>${backButton()}<button onclick="navigate('daily')">Practice Another Category</button></div>`}else showPractice()}
async function announcements(){const d=await api('/api/announcements');app.innerHTML=`${sectionHeader('📢','Announcements','Important student updates and notices.')} ${cardGrid(d)}`}
async function calendar(){const d=await api('/api/calendar');app.innerHTML=`${sectionHeader('📅','Academic Calendar','Important academic dates and events.')} ${cardGrid(d)}`}
async function links(){const d=await api('/api/useful_links');app.innerHTML=`${sectionHeader('🔗','Useful Links','Quick access to important student resources and websites.')} ${cardGrid(d)}`}
async function login(){app.innerHTML=`${sectionHeader('🔐','Admin Login','Authorized administrators can manage portal content.')}<div class="login-card"><div class="login-art">⚙️</div><input id="em" placeholder="Email" value="admin@college.com"><input id="pw" type="password" placeholder="Password" value="admin123"><button onclick="doLogin()">Login to Admin →</button><div id="lm"></div></div>`}
async function doLogin(){try{const d=await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:em.value,password:pw.value})});token=d.token;localStorage.adminToken=token;admin=true;drawNav();navigate('admin')}catch(e){lm.innerHTML=`<div class="notice danger">${esc(e.message)}</div>`}}
async function adminPage(){if(!admin)return login();const items=[['companies','🏢 Companies'],['jobs','🔔 Jobs & Internships'],['placement_questions','📝 Placement Questions'],['technical_resources','🛠️ Technical Resources'],['interview_questions','🎤 Interview Questions'],['daily_practice','📅 Daily Practice'],['resources','📚 E-Library'],['courses','📜 Courses'],['projects','🚀 Projects'],['announcements','📢 Announcements'],['calendar','📅 Calendar'],['useful_links','🔗 Useful Links'],['results','🎓 Results']];app.innerHTML=`${sectionHeader('⚙️','Admin Dashboard','Manage the student-facing portal content without changing its structure.')}<div class="admin-grid">${items.map(x=>`<article class="admin-card"><span>${x[1].split(' ')[0]}</span><h3>${x[1].slice(2)}</h3><button onclick="openView('admin:'+${JSON.stringify(x[0])},()=>adminManage('${x[0]}'))">Manage →</button></article>`).join('')}</div>`}
async function adminManage(kind){
 const d=await api('/api/'+kind);
 if(kind==='results'){
   const sem=[1,2,3,4,5,6,7,8];
   const rows=sem.map(n=>d.find(x=>String(x.semester)===String(n)&&x.type==='semester')||{});
   app.innerHTML=`${sectionHeader('⚙️','Manage Results','Enter semester SGPA (and optional semester credits). CGPA and percentage are calculated automatically on the student Results page.')}
   <div class="results-admin-hero"><b>🌐 Official VTU Results</b><p>Use the official VTU result website to verify marks. The portal never asks students to enter a VTU username or password.</p><a class="btn" target="_blank" rel="noopener" href="https://totalresults.vtu.ac.in/">Open Official VTU Results →</a></div>
   <form id="rf" class="results-admin-form"><div class="results-admin-grid">${sem.map(n=>`<label><span>📘 Semester ${n} SGPA</span><input name="sgpa${n}" type="number" min="0" max="10" step="0.01" value="${rows[n-1].sgpa??''}" placeholder="e.g. 8.25"><small>Optional credits</small><input name="credits${n}" type="number" min="1" step="1" value="${rows[n-1].credits||''}" placeholder="e.g. 24"></label>`).join('')}</div><div class="admin-result-actions"><button type="submit">💾 Save Semester Results</button><button type="button" class="secondary" onclick="replaceView('admin:results',()=>adminManage('results'))">↻ Reload</button></div><p class="admin-result-help">Leave a semester blank until its official result is available. Once SGPA values are entered, the student Results page automatically updates CGPA, percentage and the recorded-semester count.</p><div id="rfm"></div></form>`;
   document.getElementById('rf').onsubmit=async e=>{
     e.preventDefault();
     const f=new FormData(e.target), semesters=[];
     for(let n=1;n<=8;n++){const sg=String(f.get('sgpa'+n)||'').trim(),cr=String(f.get('credits'+n)||'').trim();if(sg!=='') semesters.push({semester:n,sgpa:Number(sg),credits:cr===''?0:Number(cr)});}
     if(semesters.some(x=>!Number.isFinite(x.sgpa)||x.sgpa<0||x.sgpa>10))return alert('Enter SGPA between 0 and 10.');
     try{await api('/api/results/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({semesters})});replaceView('admin:results',()=>adminManage('results'));}catch(err){document.getElementById('rfm').innerHTML=`<div class="notice danger">${esc(err.message)}</div>`}
   };
   return;
 }
 app.innerHTML=`${sectionHeader('⚙️',`Manage ${esc(kind.replaceAll('_',' '))}`,'Add, edit and delete records. Technical resources support PDF or URL upload.')} ${kind==='technical_resources'?`<form id="uf" class="card admin-form"><select name="skill">${skills.map(x=>`<option>${x}</option>`).join('')}</select><select name="type"><option>Notes / PDF Resource</option><option>Useful Link</option><option>Video</option></select><input name="title" placeholder="Resource title" required><input name="description" placeholder="Description"><input name="url" placeholder="Optional URL"><input name="file" type="file" accept=".pdf"><button>Add Resource</button></form>`:`<form id="af" class="card admin-form"><textarea name="json" rows="8" placeholder='Paste one JSON object to add an entry' required></textarea><button>Add Entry</button></form>`}<div class="grid">${d.slice(0,150).map(x=>`<article class="card"><h3>${esc(x.title||x.name||x.company||x.question||x.skill||'Entry')}</h3><p class="small">ID: ${esc(x.id)}</p><button class="secondary" onclick="adminEdit('${kind}',${x.id})">Edit</button><button class="danger" onclick="adminDelete('${kind}',${x.id})">Delete</button></article>`).join('')}</div>`;
 const f=document.getElementById('af');
 if(f)f.onsubmit=async e=>{e.preventDefault();let o;try{o=JSON.parse(e.target.json.value)}catch{return alert('Invalid JSON')};await api('/api/'+kind,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});replaceView('admin:'+kind,()=>adminManage(kind))};
 const uf=document.getElementById('uf');
 if(uf)uf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),file=fd.get('file');let base='';if(file&&file.size)base=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]||'');r.onerror=rej;r.readAsDataURL(file)});await api('/api/technical_resources/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({skill:fd.get('skill'),type:fd.get('type'),title:fd.get('title'),description:fd.get('description'),url:fd.get('url'),fileName:file?.name,fileBase64:base})});replaceView('admin:'+kind,()=>adminManage(kind))}
}
async function adminDelete(kind,id){if(confirm('Delete this entry?')){await api('/api/'+kind+'/'+id,{method:'DELETE'});replaceView('admin:'+kind,()=>adminManage(kind))}}
async function adminEdit(kind,id){const d=await api('/api/'+kind),x=d.find(v=>String(v.id)===String(id));if(!x)return;const raw=prompt('Edit entry as JSON',JSON.stringify(x,null,2));if(!raw)return;try{const o=JSON.parse(raw);delete o.id;await api('/api/'+kind+'/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});replaceView('admin:'+kind,()=>adminManage(kind))}catch(e){alert('Invalid JSON or update failed: '+e.message)}}
drawNav();render('home');
